
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbefe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbefe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.368053098845612e+00, -4.286850352738614e+00, -4.173149296875871e+00, -4.015811419003090e+00, -3.801738960814006e+00, -3.517399775163795e+00, -3.152283473647017e+00, -2.704546137448137e+00, -2.186636815763410e+00, -1.625858199490484e+00, -1.079445746610694e+00, -7.176014004283665e-01, -6.084572075335393e-01, -5.117680425203129e-01, -3.772009586425743e-01, -2.362280939957884e-01, -1.161702867382575e-01, -3.999376645042486e-02, -8.618198075303099e-03, -9.687903345059923e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


